dataSet.query:
ВЫБРАТЬ РАЗРЕШЕННЫЕ РАЗЛИЧНЫЕ СтатистикаСделокСКлиентами.ЭтапПроцесса КАК Этап ПОМЕСТИТЬ Этапы ИЗ РегистрСведений.СтатистикаСделокСКлиентами КАК СтатистикаСделокСКлиентами ГДЕ СтатистикаСделокСКлиентами.Сделка.ДатаНачала <= &КонецПериода И (СтатистикаСделокСКлиентами.Сделка.ДатаОкончания >= &НачалоПериода ИЛИ СтатистикаСделокСКлиентами.Сделка.ДатаОкончания = ДАТАВРЕМЯ(1, 1, 1)) ;
//////////////////////////////////////////////////////////////////////////////// ВЫБРАТЬ РАЗРЕШЕННЫЕ РАЗЛИЧНЫЕ СтатистикаСделокСКлиентами.Сделка ПОМЕСТИТЬ Сделки ИЗ РегистрСведений.СтатистикаСделокСКлиентами КАК СтатистикаСделокСКлиентами ГДЕ СтатистикаСделокСКлиентами.Сделка.ДатаНачала <= &КонецПериода И (СтатистикаСделокСКлиентами.Сделка.ДатаОкончания >= &НачалоПериода ИЛИ СтатистикаСделокСКлиентами.Сделка.ДатаОкончания = ДАТАВРЕМЯ(1, 1, 1)) ;
//////////////////////////////////////////////////////////////////////////////// ВЫБРАТЬ РАЗРЕШЕННЫЕ РАЗЛИЧНЫЕ СтатистикаСделокСКлиентами.ЭтапПроцесса КАК Этап, СтатистикаСделокСКлиентами.Сделка КАК Сделка, СтатистикаСделокСКлиентами.Результат КАК СтатусНаЭтапе, СтатистикаСделокСКлиентами.Сделка КАК КолВоСделок, СтатистикаСделокСКлиентами.Сделка.ВидСделки КАК ВидСделки, СтатистикаСделокСКлиентами.Ответственный КАК Ответственный, СтатистикаСделокСКлиентами.Сделка.Партнер КАК Партнер, СтатистикаСделокСКлиентами.Результат КАК Статус ПОМЕСТИТЬ Данные ИЗ РегистрСведений.СтатистикаСделокСКлиентами КАК СтатистикаСделокСКлиентами ГДЕ СтатистикаСделокСКлиентами.Сделка.ДатаНачала <= &КонецПериода И (СтатистикаСделокСКлиентами.Сделка.ДатаОкончания >= &НачалоПериода ИЛИ СтатистикаСделокСКлиентами.Сделка.ДатаОкончания = ДАТАВРЕМЯ(1, 1, 1)) {ГДЕ СтатистикаСделокСКлиентами.Сделка.*, СтатистикаСделокСКлиентами.Сделка.ВидСделки.* КАК ВидСделки, СтатистикаСделокСКлиентами.Ответственный.*, СтатистикаСделокСКлиентами.Сделка.Партнер.* КАК Партнер} ;
//////////////////////////////////////////////////////////////////////////////// ВЫБРАТЬ ВЫигранныеСделки.Сделка КАК Сделка, ВЫигранныеСделки.Этап КАК Этап, ЗНАЧЕНИЕ(Перечисление.СтатусыСделок.Выиграна) КАК СтатусНаЭтапе, ВЫигранныеСделки.Сделка.ВидСделки КАК ВидСделки, ВЫигранныеСделки.Сделка.Ответственный КАК Ответственный, ВЫигранныеСделки.Сделка.Партнер КАК Партнер, ВЫигранныеСделки.Сделка.Статус КАК Статус, ВЫигранныеСделки.Сделка КАК КолВоСделок, ВЫигранныеСделки.Сделка.ПотенциальнаяСуммаПродажи КАК Потенциал {ВЫБРАТЬ Сделка.*, Этап.*, СтатусНаЭтапе.*, ВидСделки.*, Ответственный.*, Партнер.*, Статус.*, КолВоСделок.*, Потенциал} ИЗ (ВЫБРАТЬ Сделки.Сделка КАК Сделка, Этапы.Этап КАК Этап ИЗ Сделки КАК Сделки, Этапы КАК Этапы) КАК ВЫигранныеСделки ЛЕВОЕ СОЕДИНЕНИЕ Данные КАК Данные ПО ВЫигранныеСделки.Сделка = Данные.Сделка И ВЫигранныеСделки.Этап.РеквизитДопУпорядочивания >= Данные.Этап.РеквизитДопУпорядочивания И (Данные.СтатусНаЭтапе <> ЗНАЧЕНИЕ(Перечисление.СтатусыСделок.Выиграна)) ГДЕ (НЕ Данные.Сделка ЕСТЬ NULL ) {ГДЕ ВЫигранныеСделки.Сделка.*, ВЫигранныеСделки.Этап.*, (ЗНАЧЕНИЕ(Перечисление.СтатусыСделок.Выиграна)).* КАК СтатусНаЭтапе, ВЫигранныеСделки.Сделка.ВидСделки.* КАК ВидСделки, ВЫигранныеСделки.Сделка.Ответственный.* КАК Ответственный, ВЫигранныеСделки.Сделка.Партнер.* КАК Партнер, ВЫигранныеСделки.Сделка.Статус.* КАК Статус}
ОБЪЕДИНИТЬ ВСЕ
ВЫБРАТЬ Данные.Сделка, Данные.Этап, Данные.СтатусНаЭтапе, Данные.ВидСделки, Данные.Ответственный, Данные.Партнер, Данные.Статус, Данные.Сделка, Данные.Сделка.ПотенциальнаяСуммаПродажи ИЗ Данные КАК Данные ГДЕ Данные.СтатусНаЭтапе <> ЗНАЧЕНИЕ(Перечисление.СтатусыСделок.Выиграна) {ГДЕ Данные.Сделка.*, Данные.Этап.*, Данные.СтатусНаЭтапе.* КАК СтатусНаЭтапе, Данные.ВидСделки.*, Данные.Ответственный.*, Данные.Партнер.*, Данные.Статус.*}
